nd)\n\n\tUserInputService.InputChanged:Connect(function(input)\n\t\tif not dragInput then return end\n\t\tlocal t = input.UserInputType\n\t\tif t ~= Enum.UserInputType.MouseMovement and t ~= Enum.UserInputType.Touch then return end\n\t\tapplyDrag(input)\n\tend)\n\n\tlocal function endDrag(input)\n\t\tif input ~= dragInput then return end\n\t\tdragInput = nil\n\t\tdragStart = nil\n\t\tdragPos = nil\n\tend\n\n\theader.InputEnded:Connect(endDrag)\n\tUserInputService.InputEnded:Connect(endDrag)\n\n\tminBtn.MouseButton1Click:Connect(function()\n\t\tif self.Minimized then\n\t\t\tself.Minimized = false\n\t\t\tWindowBase.tweenSize(root, root.AbsoluteSize.X, self.ContentHeight)\n\t\t\tminBtn.Text = \"—\"\n\t\telse\n\t\t\tself.Minimized = true\n\t\t\tself.ContentHeight = root.AbsoluteSize.Y\n\t\t\tWindowBase.tweenSize(root, root.AbsoluteSize.X, HEADER_H)\n\t\t\tminBtn.Text = \"+\"\n\t\tend\n\tend)\n\n\tcloseBtn.MouseButton1Click:Connect(function()\n\t\tself:Destroy()\n\tend)\n\n\tself.Gui = gui\n\tself.Root = root\n\tself.Header = header\n\tself.Content = content\n\tself.Title = title\n\tself.MinimizeButton = minBtn\n\tself.CloseButton = closeBtn\n\tself._destroyed = false\n\n\treturn self\nend\n\nfunction WindowBase:setSize(w, h)\n\tself.ContentHeight = h\n\tWindowBase.tweenSize(self.Root, w, h)\nend\n\nfunction WindowBase:setTitle(text)\n\tself.Title.Text = text\nend\n\nfunction WindowBase:bringToFront()\n\tself.Gui.DisplayOrder = (self.Gui.DisplayOrder or 0) + 1\nend\n\nfunction WindowBase:Destroy()\n\tif self._destroyed then return end\n\tself._destroyed = true\n\tif WindowBase.Registry[self.Key] == self then\n\t\tWindowBase.Registry[self.Key] = nil\n\tend\n\tif self.OnClosed then\n\t\tself.OnClosed(self)\n\tend\n\tself.Gui:Destroy()\nend\n\nenv.WindowBase = WindowBase\nreturn WindowBase" },
	{ name = "FloatingWindow.lua", key = "FloatingWindow", file = "local env = getgenv and getgenv() or _G\nif env.FloatingWindow then return env.FloatingWindow end\n\nlocal WindowBase = env.WindowBase\nassert(WindowBase, \"WindowBase не загружен\")\n\nlocal FloatingWindow = {}\nFloatingWindow.__index = FloatingWindow\n\nlocal P = WindowBase.Palette\n\nlocal MIN_W = 250\nlocal HEADER_H = 36\nlocal PAD = 8\nlocal ROW_H = 44\nlocal MAX_ROWS = 6\n\nfunction FloatingWindow.new()\n\tlocal self = setmetatable({}, FloatingWindow)\n\n\tlocal base = WindowBase.new(\"Scripts\", \"Скрипты\")\n\tself.Base = base\n\tself.Gui = base.Gui\n\tself.Root = base.Root\n\tself.Content = base.Content\n\n\tlocal list = Instance.new(\"ScrollingFrame\")\n\tlist.Name = \"List\"\n\tlist.Position = UDim2.fromOffset(PAD, PAD)\n\tlist.Size = UDim2.new(1, -PAD * 2, 1, -PAD * 2)\n\tlist.BackgroundTransparency = 1\n\tlist.BorderSizePixel = 0\n\tlist.ScrollBarThickness = 4\n\tlist.ScrollBarImageColor3 = P.line\n\tlist.CanvasSize = UDim2.fromOffset(0, 0)\n\tlist.AutomaticCanvasSize = Enum.AutomaticSize.Y\n\tlist.Parent = base.Content\n\n\tself.List = list\n\tself._lastData = nil\n\tself._sizeTween = nil\n\n\tbase:setSize(MIN_W, HEADER_H + PAD * 2)\n\treturn self\nend\n\nfunction FloatingWindow:setSize(w, h)\n\tself.Base:setSize(w, h)\nend\n\nfunction FloatingWindow:Render(listData)\n\tself._lastData = listData or {}\n\tfor _, child in ipairs(self.List:GetChildren()) do\n\t\tif child:IsA(\"TextButton\") then\n\t\t\tchild:Destroy()\n\t\tend\n\tend\n\n\tlocal count = #self._lastData\n\tlocal rows = math.min(count, MAX_ROWS)\n\tlocal windowH = math.max(HEADER_H + PAD * 2, HEADER_H + PAD * 2 + rows * ROW_H)\n\tself:setSize(MIN_W, windowH)\n\n\tif count == 0 then\n\t\tself.List.CanvasSize = UDim2.fromOffset(0, 0)\n\t\treturn\n\tend\n\n\tfor i, data in ipairs(self._lastData) do\n\t\tlocal btn = Instance.new(\"TextButton\")\n\t\tbtn.Name = \"Module_\" .. i\n\t\tbtn.Size = UDim2.new(1, 0, 0, ROW_H - 4)\n\t\tbtn.Position = UDim2.fromOffset(0, (i - 1) * ROW_H)\n\t\tbtn.BackgroundColor3 = data.hasAccess and Color3.fromRGB(47, 57, 47) or Color3.fromRGB(57, 47, 47)\n\t\tbtn.BorderSizePixel = 0\n\t\tbtn.AutoButtonColor = true\n\t\tbtn.Text = \"\"\n\t\tbtn.Parent = self.List\n\n\t\tInstance.new(\"UICorner\", btn).CornerRadius = UDim.new(0, 8)\n\n\t\tlocal status = Instance.new(\"Frame\")\n\t\tstatus.Name = \"Status\"\n\t\tstatus.Size = UDim2.fromOffset(4, ROW_H - 12)\n\t\tstatus.Position = UDim2.new(0, 4, 0.5, -(ROW_H - 12) / 2)\n\t\tstatus.BackgroundColor3 = data.hasAccess and P.accent or P.danger\n\t\tstatus.BorderSizePixel = 0\n\t\tstatus.Parent = btn\n\t\tInstance.new(\"UICorner\", status).CornerRadius = UDim.new(0, 2)\n\n\t\tlocal name = Instance.new(\"TextLabel\")\n\t\tname.Name = \"Name\"\n\t\tname.Size = UDim2.new(1, -16, 0, 18)\n\t\tname.Position = UDim2.new(0, 14, 0, 5)\n\t\tname.BackgroundTransparency = 1\n\t\tname.Text = data.name\n\t\tname.TextColor3 = P.text\n\t\tname.Font = Enum.Font.GothamSemibold\n\t\tname.TextSize = 14\n\t\tname.TextXAlignment = Enum.TextXAlignment.Left\n\t\tname.TextTruncate = Enum.TextTruncate.AtEnd\n\t\tname.Parent = btn\n\n\t\tlocal what = Instance.new(\"TextLabel\")\n\t\twhat.Name = \"What\"\n\t\twhat.Size = UDim2.new(1, -16, 0, 14)\n\t\twhat.Position = UDim2.new(0, 14, 0, 23)\n\t\twhat.BackgroundTransparency = 1\n\t\twhat.Text = (data.hasAccess and \"● \" or \"○ \") .. (data.what or \"\")\n\t\twhat.Font = Enum.Font.Gotham\n\t\twhat.TextSize = 11\n\t\twhat.TextColor3 = P.textDim\n\t\twhat.TextXAlignment = Enum.TextXAlignment.Left\n\t\twhat.TextTruncate = Enum.TextTruncate.AtEnd\n\t\twhat.Parent = btn\n\n\t\tlocal runnable = data.hasAccess\n\t\tbtn.MouseButton1Click:Connect(function()\n\t\t\tif not runnable or not data.run then return end\n\t\t\tlocal ok, err = pcall(data.run)\n\t\t\tif not ok then\n\t\t\t\twarn((\"[ControlerScript] %s: %s\"):format(data.name, tostring(err)))\n\t\t\tend\n\t\tend)\n\tend\n\n\tself.List.CanvasSize = UDim2.fromOffset(0, count * ROW_H)\nend\n\nfunction FloatingWindow:Destroy()\n\tself.Base:Destroy()\nend\n\nenv.FloatingWindow = FloatingWindow\nreturn FloatingWindow" },
	{ name = "SpeedLogic.lua", key = "SpeedLogic", file = "local env = getgenv and getgenv() or _G\nif env.SpeedLogic then return env.SpeedLogic end\n\nlocal SpeedLogic = {}\nSpeedLogic.__index = SpeedLogic\n\nlocal Players = game:GetService(\"Players\")\nlocal LocalPlayer = Players.LocalPlayer\n\nSpeedLogic.BASE_SPEED = 16\n\nlocal originalSpeed = nil\n\nfunction SpeedLogic.getHumanoid()\n\tlocal char = LocalPlayer.Character\n\tif not char then return nil end\n\treturn char:FindFirstChildOfClass(\"Humanoid\")\nend\n\nfunction SpeedLogic.canRun()\n\treturn SpeedLogic.getHumanoid() ~= nil\nend\n\nfunction SpeedLogic.getCurrentSpeed()\n\tlocal h = SpeedLogic.getHumanoid()\n\treturn h and h.WalkSpeed or 0\nend\n\nfunction SpeedLogic.setSpeed(value)\n\tlocal h = SpeedLogic.getHumanoid()\n\tif not h then return false end\n\tif originalSpeed == nil then\n\t\toriginalSpeed = h.WalkSpeed\n\tend\n\th.WalkSpeed = value\n\treturn true\nend\n\nfunction SpeedLogic.resetSpeed()\n\tlocal h = SpeedLogic.getHumanoid()\n\tif not h then return false end\n\th.WalkSpeed = originalSpeed or SpeedLogic.BASE_SPEED\n\treturn true\nend\n\nfunction SpeedLogic.getBaseSpeed()\n\treturn originalSpeed or SpeedLogic.BASE_SPEED\nend\n\nenv.SpeedLogic = SpeedLogic\nreturn SpeedLogic" },
	{ name = "SpeedInterface.lua", key = "SpeedInterface", file = "local env = getgenv and getgenv() or _G\nlocal ScriptModule = env.ScriptModule\nlocal SpeedLogic = env.SpeedLogic\nlocal WindowBase = env.WindowBase\nassert(ScriptModule, \"ScriptModule не загружен\")\nassert(SpeedLogic, \"SpeedLogic не загружен\")\nassert(WindowBase, \"WindowBase не загружен\")\n\nlocal P = WindowBase.Palette\n\nlocal window = nil\n\nlocal function openWindow()\n\tif window then\n\t\twindow:Destroy()\n\t\twindow = nil\n\t\treturn\n\tend\n\n\tlocal base = WindowBase.new(\"Speed\", \"Скорость\")\n\twindow = base\n\n\tlocal W = 260\n\tlocal H = 210\n\tlocal PAD = 10\n\tlocal btnH = 36\n\tlocal content = base.Content\n\n\tlocal status = Instance.new(\"TextLabel\")\n\tstatus.Name = \"Status\"\n\tstatus.Position = UDim2.fromOffset(PAD, PAD)\n\tstatus.Size = UDim2.new(1, -PAD * 2, 0, 22)\n\tstatus.BackgroundTransparency = 1\n\tstatus.TextColor3 = P.text\n\tstatus.Font = Enum.Font.GothamSemibold\n\tstatus.TextSize = 15\n\tstatus.TextXAlignment = Enum.TextXAlignment.Left\n\tstatus.Parent = content\n\n\tlocal box = Instance.new(\"TextBox\")\n\tbox.Name = \"SpeedBox\"\n\tbox.Position = UDim2.fromOffset(PAD, PAD + 28)\n\tbox.Size = UDim2.new(1, -PAD * 2, 0, 34)\n\tbox.BackgroundColor3 = P.panelAlt\n\tbox.BorderSizePixel = 0\n\tbox.PlaceholderText = \"Скорость\"\n\tbox.PlaceholderColor3 = P.textDim\n\tbox.TextColor3 = P.text\n\tbox.Font = Enum.Font.GothamSemibold\n\tbox.TextSize = 15\n\tbox.Parent = content\n\tInstance.new(\"UICorner\", box).CornerRadius = UDim.new(0, 8)\n\n\tlocal applyBtn = Instance.new(\"TextButton\")\n\tapplyBtn.Name = \"Apply\"\n\tapplyBtn.Position = UDim2.fromOffset(PAD, PAD + 28 + 42)\n\tapplyBtn.Size = UDim2.new(1, -PAD * 2, 0, btnH)\n\tapplyBtn.BackgroundColor3 = P.accent\n\tapplyBtn.BorderSizePixel = 0\n\tapplyBtn.Text = \"Применить\"\n\tapplyBtn.TextColor3 = Color3.new(1, 1, 1)\n\tapplyBtn.Font = Enum.Font.GothamSemibold\n\tapplyBtn.TextSize = 16\n\tapplyBtn.Parent = con